+// Selected command or argument.
+func (c *Context) Selected() *Node {
+	var selected *Node
+	for _, path := range c.Path {
+		switch {
+		case path.Command != nil:
+			selected = path.Command
+		case path.Argument != nil:
+			selected = path.Argument
+		}
+	}
